begin;
create table trade_business.order_customs_revisions(company_id uuid not null,id uuid not null,order_id uuid not null,line_id uuid not null,before_value jsonb not null,after_value jsonb not null,reason text not null,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(company_id,id),foreign key(company_id,order_id,line_id) references trade_business.order_lines(company_id,order_id,id));
create index customs_revision_line on trade_business.order_customs_revisions(company_id,line_id,created_at desc);
create table trade_business.refund_items(company_id uuid not null,order_id uuid not null,key text not null check(key in ('export_contract','purchase_contract','purchase_invoice','customs','transport','ci_pl','collection')),status text not null default 'missing' check(status in ('missing','uploaded','pending_review','reviewed','not_applicable')),version integer not null default 1 check(version>0),reference text not null default '',reason text not null default '',reviewed_by uuid,primary key(company_id,order_id,key),foreign key(company_id,order_id) references trade_business.orders(company_id,id));
create table trade_business.refund_item_files(company_id uuid not null,order_id uuid not null,key text not null,file_id uuid not null,primary key(company_id,order_id,key,file_id),foreign key(company_id,order_id,key) references trade_business.refund_items(company_id,order_id,key),foreign key(company_id,order_id,file_id) references trade_business.file_assets(company_id,order_id,id));
create table trade_business.refund_reviews(company_id uuid not null,id uuid not null,order_id uuid not null,key text not null,actor_id uuid not null,status text not null,reason text not null,file_ids jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),primary key(company_id,id),foreign key(company_id,order_id,key) references trade_business.refund_items(company_id,order_id,key));
create table trade_business.refund_exports(company_id uuid not null,id uuid not null,order_id uuid not null,format text not null check(format in ('csv','pdf','zip')),snapshot jsonb not null,state text not null default 'pending' check(state in ('pending','stored')),file_id uuid,claim_id uuid,claim_until timestamptz,created_by uuid not null,primary key(company_id,id),foreign key(company_id,order_id) references trade_business.orders(company_id,id),foreign key(company_id,file_id) references trade_business.file_assets(company_id,id));
grant select,insert on trade_business.refund_exports to business_backend;
grant update(state,file_id,claim_id,claim_until) on trade_business.refund_exports to business_backend;
grant select,insert on trade_business.order_customs_revisions,trade_business.refund_items,trade_business.refund_item_files,trade_business.refund_reviews to business_backend;
grant update(status,version,reference,reason,reviewed_by) on trade_business.refund_items to business_backend;
grant delete on trade_business.refund_item_files to business_backend;
commit;
